"""Roll raw samples up into fixed-width time windows."""

from .window import floor_to_window


class RollupError(ValueError):
    """Raised when a rollup request cannot be satisfied."""


class Sample(object):
    """A single measurement at an integer-nanosecond instant."""

    __slots__ = ("ts", "value")

    def __init__(self, ts, value):
        if not isinstance(ts, int) or isinstance(ts, bool):
            raise TypeError("ts must be an int")
        self.ts = ts
        self.value = float(value)

    def __repr__(self):
        return "Sample(ts=%d, value=%r)" % (self.ts, self.value)

    def __eq__(self, other):
        if not isinstance(other, Sample):
            return NotImplemented
        return self.ts == other.ts and self.value == other.value


def rollup(samples, width):
    """Group ``samples`` into windows of ``width`` nanoseconds.

    Returns a list of ``(window_start, count, total)`` triples ordered by
    ``window_start``. Windows with no samples are omitted. ``width`` must be a
    positive integer number of nanoseconds.
    """
    if not isinstance(width, int) or isinstance(width, bool):
        raise TypeError("width must be an int")
    if width <= 0:
        raise RollupError("width must be positive, got %d" % (width,))

    buckets = {}
    for sample in samples:
        if not isinstance(sample, Sample):
            raise RollupError("expected Sample, got %r" % (type(sample).__name__,))
        start = floor_to_window(sample.ts, width)
        count, total = buckets.get(start, (0, 0.0))
        buckets[start] = (count + 1, total + sample.value)

    return [(start, c, t) for start, (c, t) in sorted(buckets.items())]
